using System;
using System.IO;
using System.Security.Principal;
using System.Security.AccessControl;
using System.Linq;
using System.Runtime.InteropServices;
public static class StartupTask {
 public static string Name {get{return "CorePilot-"+WindowsIdentity.GetCurrent().User.Value;}}
 static void CheckWriteAces(FileSystemSecurity security,string path){var dangerous=FileSystemRights.Write|FileSystemRights.Modify|FileSystemRights.Delete|FileSystemRights.DeleteSubdirectoriesAndFiles|FileSystemRights.ChangePermissions|FileSystemRights.TakeOwnership|FileSystemRights.CreateFiles|FileSystemRights.CreateDirectories;var user=WindowsIdentity.GetCurrent().User;var untrusted=new[]{new SecurityIdentifier("S-1-1-0"),new SecurityIdentifier("S-1-5-11"),new SecurityIdentifier("S-1-5-32-545"),user};foreach(FileSystemAccessRule rule in security.GetAccessRules(true,true,typeof(SecurityIdentifier))){var sid=(SecurityIdentifier)rule.IdentityReference;if(rule.AccessControlType==AccessControlType.Allow&&untrusted.Any(x=>x.Equals(sid))&&(rule.FileSystemRights&dangerous)!=0)throw new InvalidOperationException("计划任务程序文件或目录允许普通用户写入，已阻止高权限自启："+path);}}
 public static void ValidateInstall(string exe){exe=Path.GetFullPath(exe);var programFiles=Path.GetFullPath(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles)).TrimEnd(Path.DirectorySeparatorChar);if((File.GetAttributes(programFiles)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("Program Files 包含重解析点，已阻止高权限自启。");CheckWriteAces(Directory.GetAccessControl(programFiles,AccessControlSections.Access),programFiles);var expected=Path.Combine(programFiles,"CorePilot");if(!exe.StartsWith(expected+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("为防止高权限程序被替换，请先将 CorePilot 安装到 Program Files\\CorePilot，再启用登录自启。");var directory=Path.GetDirectoryName(exe);for(var current=directory;current!=null&&current.StartsWith(expected,StringComparison.OrdinalIgnoreCase);current=Path.GetDirectoryName(current)){if((File.GetAttributes(current)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("安装目录包含重解析点，已阻止高权限自启。");CheckWriteAces(Directory.GetAccessControl(current,AccessControlSections.Access),current);if(current.Equals(expected,StringComparison.OrdinalIgnoreCase))break;}if(!File.Exists(exe)||(File.GetAttributes(exe)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("程序文件不存在或属于重解析点。");CheckWriteAces(File.GetAccessControl(exe,AccessControlSections.Access),exe);}
 public static string Register(string exe,string taskName=null,string arguments="--silent"){exe=Path.GetFullPath(exe);ValidateInstall(exe);if(!File.Exists(exe))throw new FileNotFoundException(exe);dynamic service=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));service.Connect();dynamic folder=service.GetFolder("\\");dynamic definition=service.NewTask(0);definition.RegistrationInfo.Description="CorePilot：用户登录后以最高权限静默托盘运行，默认 CCD1，按主动规则管理进程树。";definition.Principal.UserId=WindowsIdentity.GetCurrent().User.Value;definition.Principal.LogonType=3;definition.Principal.RunLevel=1;definition.Settings.Enabled=true;definition.Settings.Hidden=true;definition.Settings.StartWhenAvailable=true;definition.Settings.DisallowStartIfOnBatteries=false;definition.Settings.StopIfGoingOnBatteries=false;definition.Settings.ExecutionTimeLimit="PT0S";definition.Settings.MultipleInstances=2;definition.Settings.RestartCount=3;definition.Settings.RestartInterval="PT1M";dynamic trigger=definition.Triggers.Create(9);trigger.UserId=definition.Principal.UserId;trigger.Delay="PT10S";dynamic action=definition.Actions.Create(0);action.Path=exe;action.Arguments=arguments;action.WorkingDirectory=Path.GetDirectoryName(exe);dynamic registered=folder.RegisterTaskDefinition(taskName??Name,definition,6,null,null,3,null);var xml=(string)registered.Xml;File.WriteAllText(Path.Combine(AppStore.DirectoryPath,"startup-task.xml"),xml);return xml;}
 public static bool Exists(){try{dynamic service=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));service.Connect();dynamic task=service.GetFolder("\\").GetTask(Name);return (bool)task.Enabled;}catch{return false;}}
 public static void Remove(){dynamic service=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));service.Connect();service.GetFolder("\\").DeleteTask(Name,0);}
}



